typedef struct { long id; char name[64]; } user_row;

static const char *SQL_INSERT = "INSERT INTO users(id, name) VALUES(?, ?)";

int users_insert(sqlite3 *db, const user_row *r) {
    sqlite3_stmt *st;
    if (sqlite3_prepare_v2(db, SQL_INSERT, -1, &st, NULL) != SQLITE_OK) return -1;
    sqlite3_bind_int64(st, 1, r->id);
    sqlite3_bind_text(st, 2, r->name, -1, SQLITE_STATIC);
    int rc = sqlite3_step(st) == SQLITE_DONE ? 0 : -1;
    sqlite3_finalize(st);            /* every prepare needs a finalize */
    return rc;
}
